# -*- coding: utf-8 -*-
"""觀點頁「換你問」面板（與 patch_site.py 的 ASK_PANEL 逐字節相同；ask16 含鍵盤 a11y）。

引擎原生輸出後，patch_site 端以 data-v=\"ask16\" 守門自動跳過，成為純安全網。
若要改版：改 patch_site.py 產生新版（bump data-v），再同步回這裡。"""

ASK_PANEL = r'''<div class="section-title">🎤 換你問：點上面選一位，再選問題</div><div id="askpanel" data-v="ask16" style="background:linear-gradient(180deg,rgba(255,255,255,.06),rgba(255,255,255,.02));border:1px solid rgba(255,255,255,.1);border-radius:16px;padding:15px 16px;margin-bottom:14px"><div id="askhint" class="lbl">👆 點上面任一張立場卡片，再從下拉選問題</div><select id="askq" class="asksel" disabled><option value="">先選一位…</option></select><div id="askans"></div><div style="font-size:11px;color:#8b96a8;margin-top:13px">以投資流派為框架推演・非本人發言・非投資建議</div></div><style>#askpanel .lbl{font-size:12.5px;color:#aab4c6;margin:0 0 10px}#askpanel .asksel{width:100%;background:rgba(255,255,255,.07);color:#eaf0fa;border:1px solid rgba(255,255,255,.16);border-radius:12px;padding:11px 12px;font-size:14px;font-family:inherit;cursor:pointer}#askpanel .asksel:disabled{opacity:.5;cursor:not-allowed}#askpanel .asksel option{background:#11203f;color:#eaf0fa}#askpanel .bubble{display:flex;gap:10px;align-items:flex-start;margin-top:13px}#askpanel .av{flex:none;width:40px;height:40px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff;font-size:13px;font-weight:800;letter-spacing:.5px;text-shadow:0 1px 3px rgba(0,0,0,.35);box-shadow:0 0 0 3px rgba(255,255,255,.06)}#askpanel .bub{border:1px solid;border-radius:4px 16px 16px 16px;padding:14px 17px;font-size:16px;line-height:1.85;color:#eaf3ff;-webkit-backdrop-filter:blur(18px) saturate(1.6);backdrop-filter:blur(18px) saturate(1.6);box-shadow:0 8px 26px rgba(0,0,0,.35),inset 0 1px 0.5px rgba(255,255,255,.18)}#askpanel .bn{font-weight:700;font-size:13px;margin-bottom:5px}.card.askpick{cursor:pointer}.card.askpick:focus-visible{outline:2px solid #8b5cf6;outline-offset:2px}</style><script>(function(){var Q=["現在能進場嗎？", "0050 還是自己挑個股？", "崩盤了怎麼辦？", "該停損嗎？", "新手第一步該做什麼？", "大家都在賺、FOMO 怎麼辦？", "定期定額還是單筆 All in？", "該借錢／融資加大部位嗎？", "怎麼看「進場分數」這個工具？", "你最反對哪種做法？"],A={"passive": ["別問時機。你問『現在能不能進場』的當下，就已經掉進擇時陷阱了。照原定定期定額扣下去、別停，就這麼簡單。", "0050 或全球 VT。挑個股長期勝率輸大盤又耗時，把力氣省下來做資產配置跟再平衡。", "崩盤是定期定額的好朋友——同樣的錢買到更多單位。繼續扣、別看帳戶、別亂動。", "不停損。指數不會歸零，停損只會讓你賣在最低點、賣掉未來的複利。", "先把緊急備用金存好，再開低成本指數 ETF 定期定額，然後……什麼都別做。", "別人賺的是別人的，你追進去通常買在高點。FOMO 是擇時的另一個名字，紀律定額就不會 FOMO。", "有閒錢其實單筆＋長期持有期望值最高；但人性受不了，所以定期定額讓你睡得著、比較實際。", "絕對不要。槓桿會在你最撐不住時斷頭，被動投資的核心就是『活得夠久』。", "有趣，但別當買賣訊號。長期而言擇時贏不過低成本紀律定額，這分數頂多當市場溫度看看。", "擇時。再準的訊號，長期都贏不過『低成本＋紀律定額＋不亂動』。"], "macro": ["先看景氣位置。現在偏『過熱』、融資槓桿暴增、Fed 全年沒幾碼——這種時候我偏防禦、重現金流，不追估值。", "都行，但重點是『質』。景氣轉折期挑有現金流、低負債的公司，比追題材安全。", "崩盤前通常信用利差和流動性會先壞。真的來了，手上要有現金跟防禦部位能接，而不是被迫殺低。", "我看的是景氣／基本面訊號轉壞才減碼，不是盯著價格停損——價格會騙人，循環不會。", "先學會看幾個總經溫度計：景氣對策信號、利率、殖利率曲線。知道現在是循環哪一段，比挑股票重要。", "市場最樂觀、人人都賺的時候，常常就是循環頂部。FOMO 最強時，我反而開始降風險。", "看循環。過熱、估值貴時我傾向分批、留現金；循環落底才是單筆布局的好時機。", "景氣過熱＋槓桿暴增的環境，加槓桿最危險。流動性一收，高槓桿的先出局。", "當環境溫度計不錯，但我更在意背後的景氣位置、利率和信用——分數高低要搭循環一起看。", "在景氣過熱、槓桿暴增時還追高估值和題材，完全不看流動性與信用轉折。"], "trend": ["趨勢還偏多、動能在，可以參與。但散戶融資在追、噴發脆弱度高，所以控部位、別 All in、留銀彈。", "看你功力。要挑個股就嚴設停損、順勢做；沒把握就定期定額 0050，別兩邊都半吊子。", "跌破 50 日線我就減碼，留的銀彈這時候才有用。別凹單、別往下攤平。", "一定要。停損是活下來的關鍵，別當那隻追高被套、捨不得停損的韭菜。", "先學會『控制部位』跟『設停損』，這兩個比選股重要十倍。先想怎麼不被抬出場，再想賺大錢。", "FOMO 進場的單，十之八九買在波段高點。手癢時問自己：停損點設在哪？設不出來就別進。", "順勢分批進、別一次梭哈。留銀彈不是膽小，是讓你回檔時還有子彈、還睡得著。", "散戶融資追高是賠大錢頭號死因。要用槓桿也是高手在低風險區小量用，不是追高 All in。", "拿來當『該積極還是收手』的提醒不錯——分數低我多留銀彈，分數高也不無腦重壓。", "重壓 All in、追高、不設停損——散戶賠大錢三件套，中一個就夠你受的。"], "value": ["看的不是時機，是價格。這家公司現在比它的內在價值便宜嗎？夠便宜（有安全邊際）就買，貴就等，跟大盤分數無關。", "挑個股，但只挑你看得懂、有護城河的好公司。看不懂的不碰；沒把握判斷價值，那就乖乖買指數，別半調子。", "崩盤是好公司打折出清——這時候我最興奮。前提是手上有現金、清單早就列好，別人恐慌時我進場撿便宜。", "我不看股價停損，我看『當初買的理由有沒有壞掉』。基本面、護城河沒變就續抱甚至加碼；論點錯了才認錯出場。", "先學會看財報、學會『怎麼估一家公司值多少錢』。看不懂估值之前，先買指數別亂挑股。能力圈，慢慢擴。", "別人瘋搶、估值噴上天時，正是我該冷靜甚至減碼的時候。便宜才買，貴了我寧可空手等下一次。", "找到夠便宜的好公司，我會單筆重押在懂的標的；沒便宜貨時就抱現金等，不為了進場而進場。", "不借錢。槓桿會讓你在市場非理性的期間被迫賣在最低點——『活得夠久』才等得到價值實現。", "當市場情緒溫度計看看可以。分數低＝市場恐慌＝我撿便宜的機會；但買不買，最終看個股的價格 vs 價值。", "追高。買在貴的價格、沒有安全邊際，再好的公司也會套牢——『好公司』和『好價格』是兩回事。"], "chips": ["看錢往哪流。外資、投信連續買超、台指期外資淨未平倉偏多就站多方；法人在調節、未平倉翻空就先收手。跟主力同一邊。", "挑法人有在買、籌碼集中的個股。但你資訊比法人慢，要嘛跟得夠快、要嘛就買指數，別瞎跟被巴。", "看是誰在賣。法人停損式倒貨、融資斷頭潮通常是末段——等籌碼洗乾淨、外資回頭買超再進，別接還在跌的刀。", "籌碼翻空就走：法人連續賣超、外資台指期未平倉由多翻空、跌破關鍵量價就減碼。籌碼是領先訊號，別凹。", "先學會看每天三大法人買賣超、外資台指期未平倉、融資融券變化。知道錢往哪流，比聽明牌有用。", "散戶融資狂追、人人都在賺的時候，常常就是主力準備出貨給你。FOMO 進場＝當被收割的那一方。", "跟著籌碼節奏分批進出，不無腦定額也不一次梭哈。法人買我加、法人撤我減。", "散戶融資追高是被收割的頭號訊號。我把融資水位當『過熱指標』看，不會自己跳進去當那個融資戶。", "分數裡的籌碼面（法人、台指期未平倉）我最看重，其餘當參考。籌碼會說話，價格只是結果。", "跟散戶一起追高、跟大戶對作。籌碼明明在倒貨還死多頭，遲早被抬出場。"]},NAME={"passive": "被動指數派", "macro": "總經循環派", "trend": "順勢紀律派", "value": "價值派", "chips": "籌碼派"},ABBR={"passive": "被動", "macro": "總經", "trend": "順勢", "value": "價值", "chips": "籌碼"};
var SEL=document.getElementById("askq"),AN=document.getElementById("askans"),HINT=document.getElementById("askhint"),cards={},DNAME={},cur=null;
var PCOL={passive:"#06d6e0",chips:"#3d8bff",trend:"#5b6cff",macro:"#c462ff",value:"#ff5fb0"};
function keyOf(t){return (t.indexOf("被動")>=0||t.indexOf("清")>=0)?"passive":(t.indexOf("總經")>=0||t.indexOf("財經")>=0)?"macro":(t.indexOf("價值")>=0)?"value":(t.indexOf("籌碼")>=0)?"chips":(t.indexOf("順勢")>=0||t.indexOf("股")>=0)?"trend":null;}
function rgba(h,a){var r=parseInt(h.slice(1,3),16),g=parseInt(h.slice(3,5),16),b=parseInt(h.slice(5,7),16);return "rgba("+r+","+g+","+b+","+a+")";}
function glass(h){return "linear-gradient(180deg,"+rgba(h,0.22)+","+rgba(h,0.06)+")";}
SEL.innerHTML='<option value="">— 選一個問題 —</option>'+Q.map(function(q,i){return '<option value="'+i+'">'+q+'</option>';}).join("");
[].forEach.call(document.querySelectorAll(".card .name"),function(n){var k=keyOf(n.textContent||"");if(!k)return;var c=n.closest(".card");if(!c)return;cards[k]=c;DNAME[k]=(n.textContent||"").replace(/\s+/g,"");c.style.setProperty("background",glass(PCOL[k]),"important");c.style.setProperty("border-color",rgba(PCOL[k],0.5),"important");c.style.setProperty("box-shadow","inset 0 1px 0.5px rgba(255,255,255,.22)","important");var d=c.querySelector(".dot");if(d)d.style.setProperty("background",PCOL[k],"important");c.classList.add("askpick");c.setAttribute("tabindex","0");c.setAttribute("role","button");c.setAttribute("aria-label","選擇 "+DNAME[k]);c.addEventListener("click",function(){pick(k);});c.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();pick(k);}});});
function render(){if(cur===null||!SEL.value){AN.innerHTML="";return;}var i=+SEL.value,c=PCOL[cur];AN.innerHTML='<div class="bubble"><div class="av" style="background:'+c+'">'+ABBR[cur]+'</div><div class="bub" style="border-color:'+c+';background:'+glass(c)+'"><div class="bn" style="color:'+c+'">'+DNAME[cur]+'</div>'+A[cur][i]+'</div></div>';}
function pick(k){cur=k;for(var x in cards){cards[x].style.outline=(x===k?"2px solid "+PCOL[k]:"");cards[x].style.outlineOffset="2px";}HINT.innerHTML="已選 <b style='color:"+PCOL[k]+"'>"+DNAME[k]+"</b>　選個問題，或點別位比較 👇";SEL.disabled=false;render();}
SEL.addEventListener("change",render);
})();</script>'''

GRID5_STYLE = r'''<style id="grid5">.grid .card:last-child:nth-child(odd){grid-column:1/-1}</style>'''
